{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

      // kaleido crap
    vec2 iuv =fract(2.0*abs(uv-0.5));
    vec2 cuv = fract(iuv*2.0*abs(iuv-0.5));

    // noise velocity field
    vec3 col = inoise(cuv, iTime*0.5);

    // Output to screen
