void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 pxs = 5.0/iResolution.xy;

    vec2 guv = 2.0*abs(fract(5.0*uv)-0.5);    
    guv.x *= iResolution.x/iResolution.y;

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime*0.1+uv.xyx+vec3(0,2,4));

    float fact = 0.7*sin(iTime*0.15);
    float div = 1.0/iResolution.x;
    fragColor = vec4(
    max(
        vec3(smoothstep(0.1,0.0, max(guv.x,guv.y)))*col,
        (1.0-(1.0/300.0))*
        (
            0.25*texture(iChannel1, 
                vec2(-0.5,-0.5)*pxs+uv+        
                (fact*texture(iChannel0, vec2(-0.25,-0.25)*pxs+uv).xy*div)        
            ).xyz +
            0.25*texture(iChannel1, 
                vec2(0.5,-0.5)*pxs+uv+        
                (fact*texture(iChannel0, vec2(0.25,-0.25)*pxs+uv).xy*div)        
            ).xyz +
            0.25*texture(iChannel1, 
                vec2(0.5,0.5)*pxs+uv+        
